import static org.junit.Assert.assertEquals;

public class LocalDate_fromCalendarFields_TriageGen0Test {



    @Test
    public void testFromCalendarFields_ValidDate_ReturnsCorrectLocalDate() {
        // Setup a specific date: 2023-10-25
        Calendar calendar = new GregorianCalendar();
        calendar.set(2023, Calendar.OCTOBER, 25);
        // Ensure time components don't interfere if implementation were different, 
        // though this method only uses year, month, and day.
        calendar.set(Calendar.HOUR_OF_DAY, 10);
        calendar.set(Calendar.MINUTE, 30);

        LocalDate result = LocalDate.fromCalendarFields(calendar);

        assertEquals(2023, result.getYear());
        assertEquals(10, result.getMonthOfYear());
        assertEquals(25, result.getDayOfMonth());
    }






}

